import { geometry } from "@aura3d/engine";

export type V3 = [number, number, number];

export const add = (a: V3, b: V3): V3 => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
export const sub = (a: V3, b: V3): V3 => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
export const mul = (a: V3, s: number): V3 => [a[0] * s, a[1] * s, a[2] * s];
export const dot = (a: V3, b: V3): number => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
export const cross = (a: V3, b: V3): V3 => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
export const len = (a: V3): number => Math.hypot(a[0], a[1], a[2]);
export const norm = (a: V3): V3 => {
  const l = len(a);
  return l < 1e-9 ? [0, 1, 0] : [a[0] / l, a[1] / l, a[2] / l];
};

/** Seeded RNG so the reef is identical on every load. */
export const makeRng = (seed: number): (() => number) => {
  let s = seed >>> 0;
  return () => {
    s = (Math.imul(s, 1664525) + 1013904223) >>> 0;
    return s / 4294967296;
  };
};

/**
 * Colour is carried in the uv attribute and decoded by the reef shader:
 * uv.x = saturation step (integer part, 0..20) + hue * 0.99, uv.y = brightness (or height along a swaying blade).
 */
export const enc = (hue: number, sat: number): number => Math.round(Math.min(Math.max(sat, 0), 1) * 20) + (hue - Math.floor(hue)) * 0.99;

export class MeshBuilder {
  private positions: number[] = [];
  private normals: number[] = [];
  private uvs: number[] = [];
  private indices: number[] = [];

  get vertexCount(): number {
    return this.positions.length / 3;
  }

  vertex(p: V3, n: V3, u: number, v: number): number {
    this.positions.push(p[0], p[1], p[2]);
    this.normals.push(n[0], n[1], n[2]);
    this.uvs.push(u, v);
    return this.positions.length / 3 - 1;
  }

  private pos(i: number): V3 {
    return [this.positions[i * 3] ?? 0, this.positions[i * 3 + 1] ?? 0, this.positions[i * 3 + 2] ?? 0];
  }

  private nrm(i: number): V3 {
    return [this.normals[i * 3] ?? 0, this.normals[i * 3 + 1] ?? 0, this.normals[i * 3 + 2] ?? 0];
  }

  /** Adds a triangle wound so its geometric normal agrees with the vertex normals. */
  triangle(a: number, b: number, c: number): void {
    const pa = this.pos(a);
    const face = cross(sub(this.pos(b), pa), sub(this.pos(c), pa));
    if (len(face) < 1e-14) return;
    const n = add(add(this.nrm(a), this.nrm(b)), this.nrm(c));
    if (dot(face, n) >= 0) this.indices.push(a, b, c);
    else this.indices.push(a, c, b);
  }

  /** Parametric surface on a (nu x nv) grid. `center` makes normals point away from it. */
  surface(
    fn: (u: number, v: number) => V3,
    nu: number,
    nv: number,
    color: (u: number, v: number, p: V3) => [number, number],
    center?: V3
  ): void {
    const base = this.vertexCount;
    const e = 1e-3;
    for (let j = 0; j <= nv; j += 1) {
      for (let i = 0; i <= nu; i += 1) {
        const u = i / nu;
        const v = j / nv;
        const p = fn(u, v);
        const vc = Math.min(Math.max(v, 2 * e), 1 - 2 * e);
        const du = sub(fn(u + e, vc), fn(u - e, vc));
        const dv = sub(fn(u, vc + e), fn(u, vc - e));
        let n = cross(du, dv);
        const l = len(n);
        n = l > 1e-12 ? mul(n, 1 / l) : [0, 1, 0];
        if (center && dot(n, sub(p, center)) < 0) n = mul(n, -1);
        const c = color(u, v, p);
        this.vertex(p, n, c[0], c[1]);
      }
    }
    for (let j = 0; j < nv; j += 1) {
      for (let i = 0; i < nu; i += 1) {
        const a = base + j * (nu + 1) + i;
        const b = a + 1;
        const c = a + nu + 1;
        const d = c + 1;
        this.triangle(a, c, b);
        this.triangle(b, c, d);
      }
    }
  }

  /** Tapered tube swept along a polyline. `val(t)` gives brightness along the path (t in 0..1). */
  tube(path: V3[], radius: (t: number) => number, sides: number, uvx: number, val: (t: number) => number): void {
    const n = path.length;
    if (n < 2) return;
    const tang: V3[] = path.map((_, i) => norm(sub(path[Math.min(i + 1, n - 1)] as V3, path[Math.max(i - 1, 0)] as V3)));
    const t0 = tang[0] as V3;
    const ref: V3 = Math.abs(t0[1]) < 0.9 ? [0, 1, 0] : [1, 0, 0];
    let nrm = norm(sub(ref, mul(t0, dot(ref, t0))));
    const base = this.vertexCount;
    for (let i = 0; i < n; i += 1) {
      const t = tang[i] as V3;
      nrm = norm(sub(nrm, mul(t, dot(nrm, t))));
      const bin = cross(t, nrm);
      const f = i / (n - 1);
      const r = radius(f);
      const c = path[i] as V3;
      for (let s = 0; s <= sides; s += 1) {
        const a = (s / sides) * Math.PI * 2;
        const dir = add(mul(nrm, Math.cos(a)), mul(bin, Math.sin(a)));
        this.vertex(add(c, mul(dir, r)), dir, uvx, val(f));
      }
    }
    for (let i = 0; i < n - 1; i += 1) {
      for (let s = 0; s < sides; s += 1) {
        const a = base + i * (sides + 1) + s;
        const b = a + 1;
        const c = a + sides + 1;
        const d = c + 1;
        this.triangle(a, c, b);
        this.triangle(b, c, d);
      }
    }
  }

  /** Flat disc facing `up`. */
  disc(center: V3, radius: number, segments: number, uvx: number, value: number, up: V3 = [0, 1, 0]): void {
    const c = this.vertex(center, up, uvx, value);
    const ref: V3 = Math.abs(up[1]) < 0.9 ? [0, 1, 0] : [1, 0, 0];
    const tx = norm(cross(up, ref));
    const tz = cross(up, tx);
    const ring: number[] = [];
    for (let s = 0; s <= segments; s += 1) {
      const a = (s / segments) * Math.PI * 2;
      const p = add(center, add(mul(tx, Math.cos(a) * radius), mul(tz, Math.sin(a) * radius)));
      ring.push(this.vertex(p, up, uvx, value));
    }
    for (let s = 0; s < segments; s += 1) this.triangle(c, ring[s] as number, ring[s + 1] as number);
  }

  build(bounds: { min: V3; max: V3 }) {
    return geometry.define({
      positions: new Float32Array(this.positions),
      normals: new Float32Array(this.normals),
      uvs: new Float32Array(this.uvs),
      indices: this.indices,
      bounds
    });
  }
}

import { material } from "@aura3d/engine";

/** Fog colour shared by the look override, the scene background and the reef shader. */
export const FOG_HEX = "#0b5b74";
export const FOG_RGB = "vec3(0.043, 0.357, 0.455)";
export const FOG_NEAR = 3;
export const FOG_FAR = 34;

export type ReefKind = "sand" | "coral" | "weed" | "anemone";

const CONFIG: Record<ReefKind, { sway: number; value: string; ao: string; micro: boolean; edge: boolean }> = {
  sand: { sway: 0, value: "float val = vUv.y;", ao: "1.0", micro: true, edge: true },
  coral: { sway: 0, value: "float val = vUv.y;", ao: "mix(0.5, 1.0, smoothstep(-0.2, 0.9, vW.y))", micro: false, edge: false },
  weed: { sway: 0.38, value: "float val = mix(0.4, 1.0, vUv.y);", ao: "mix(0.55, 1.0, smoothstep(-0.2, 1.2, vW.y))", micro: false, edge: false },
  anemone: { sway: 0.1, value: "float val = mix(0.5, 1.0, vUv.y);", ao: "mix(0.6, 1.0, smoothstep(-0.2, 0.6, vW.y))", micro: false, edge: false }
};

const num = (v: number): string => (Number.isInteger(v) ? `${v}.0` : `${v}`);

const vertexSource = (sway: number): string => /* glsl */ `
out vec3 vW;
out vec3 vN;
out vec2 vUv;
out float vT;
void main() {
  vec3 p = position;
  ${
    sway > 0
      ? `float ph = p.x * 0.9 + p.z * 0.7;
  float s = uv.y * uv.y;
  p.x += (sin(tClock * 1.1 + ph) + 0.5 * sin(tClock * 2.3 + ph * 1.7)) * ${num(sway)} * s;
  p.z += (0.8 * cos(tClock * 0.9 + ph * 1.2) + 0.3 * sin(tClock * 1.9 + ph)) * ${num(sway)} * s;`
      : ""
  }
  vW = p;
  vN = normal;
  vUv = uv;
  vT = tClock;
  gl_Position = modelViewProjectionMatrix * vec4(p, 1.0);
}`;

const fragmentSource = (kind: ReefKind): string => {
  const c = CONFIG[kind];
  return /* glsl */ `
in vec3 vW;
in vec3 vN;
in vec2 vUv;
in float vT;
out vec4 outColor;

float caustic(vec2 uv, float time) {
  vec2 p = mod(uv * 6.28318530718, 6.28318530718) - 250.0;
  vec2 i = p;
  float c = 1.0;
  float inten = 0.005;
  for (int n = 0; n < 5; n++) {
    float t = time * (1.0 - (3.5 / float(n + 1)));
    i = p + vec2(cos(t - i.x) + sin(t + i.y), sin(t - i.y) + cos(t + i.x));
    c += 1.0 / max(length(vec2(p.x / (sin(i.x + t) / inten + 0.00001), p.y / (cos(i.y + t) / inten + 0.00001))), 0.0001);
  }
  c /= 5.0;
  c = 1.17 - pow(max(c, 0.0), 1.4);
  return pow(abs(c), 8.0);
}

vec3 hsv2rgb(vec3 c) {
  vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
  vec3 q = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(K.xxx, clamp(q - K.xxx, 0.0, 1.0), c.y);
}

void main() {
  float sat = floor(vUv.x) / 20.0;
  float hue = clamp(fract(vUv.x) / 0.99, 0.0, 1.0);
  ${c.value}
  ${c.micro ? "val += (fract(sin(dot(floor(vW.xz * 45.0), vec2(12.9898, 78.233))) * 43758.5453) - 0.5) * 0.09;" : ""}
  vec3 albedo = hsv2rgb(vec3(hue, sat, val));
  vec3 N = normalize(vN);
  if (!gl_FrontFacing) N = -N;
  ${
    c.micro
      ? `float rp = dot(vW.xz, vec2(3.4, 1.5)) + 1.6 * sin(vW.z * 1.3 + vW.x * 0.4);
  N = normalize(N + vec3(0.2 * cos(rp), 0.0, 0.09 * cos(rp)));
  albedo *= 0.93 + 0.07 * sin(rp);`
      : ""
  }
  vec3 L = normalize(vec3(0.28, 1.0, 0.18));
  float ndl = max(dot(N, L), 0.0);
  float depthK = mix(0.5, 1.0, smoothstep(0.0, 9.0, vW.y + 1.0));
  vec3 sunC = vec3(0.72, 1.0, 0.93);
  vec3 amb = mix(vec3(0.05, 0.14, 0.18), vec3(0.14, 0.38, 0.46), 0.5 + 0.5 * N.y);
  float ao = ${c.ao};
  vec3 col = albedo * (amb + sunC * ndl * 1.05 * depthK) * ao;
  float cs = 0.5 * (caustic(vW.xz * 0.16, vT * 0.55) + caustic(vW.xz * 0.23 + 3.7, vT * 0.4 + 5.0));
  float up = smoothstep(-0.1, 0.8, N.y);
  float cAmt = cs * up * exp(-max(vW.y, 0.0) * 0.22) * ${kind === "sand" ? "1.25" : "0.9"};
  col += (albedo * 1.2 + 0.1) * sunC * cAmt * ao;
  col *= vec3(0.8, 1.0, 0.98);
  float d = distance(cameraPosition, vW);
  float f = clamp((d - ${num(FOG_NEAR)}) / ${num(FOG_FAR - FOG_NEAR)}, 0.0, 1.0);
  ${c.edge ? "f = max(f, smoothstep(18.0, 28.0, length(vW.xz)));" : ""}
  col = mix(col, ${FOG_RGB}, f);
  outColor = vec4(col, 1.0);
}`;
};

export const reefMaterial = (kind: ReefKind) =>
  material.custom({
    glsl: { vertex: vertexSource(CONFIG[kind].sway), fragment: fragmentSource(kind) },
    uniforms: { tClock: { type: "f32", value: 0 } },
    side: "double",
    fog: false
  });

import { MeshBuilder, add, enc, makeRng, mul, norm, type V3 } from "./mesh";

export const SAND_SIZE = 64;
const TAU = Math.PI * 2;

const ripplePhase = (x: number, z: number): number => (x * 0.8 + z * 0.35 + 1.4 * Math.sin(z * 0.21 + x * 0.05)) * 4.4;

/** Seabed height: broad dunes plus parallel sand ripples. */
export const groundY = (x: number, z: number): number => {
  const dune = 0.32 * Math.sin(x * 0.11 + 0.7) * Math.cos(z * 0.09) + 0.2 * Math.sin((x + z) * 0.07 + 2);
  return dune + 0.05 * Math.sin(ripplePhase(x, z));
};

export const buildSand = () => {
  const b = new MeshBuilder();
  const cells = 220;
  b.surface(
    (u, v) => {
      const x = (u - 0.5) * SAND_SIZE;
      const z = (v - 0.5) * SAND_SIZE;
      return [x, groundY(x, z), z];
    },
    cells,
    cells,
    (_u, _v, p) => [enc(0.11, 0.3), 0.8 + 0.07 * Math.sin(ripplePhase(p[0], p[2])) + 0.03 * Math.sin(p[0] * 0.5 + p[2] * 0.3)],
    [0, -200, 0]
  );
  return b.build({ min: [-SAND_SIZE / 2, -2, -SAND_SIZE / 2], max: [SAND_SIZE / 2, 2, SAND_SIZE / 2] });
};

const rnd = (r: () => number, a: number, c: number): number => a + (c - a) * r();

/** Staghorn-style branching coral: a few stems that fork three times. */
const branching = (b: MeshBuilder, r: () => number, cx: number, cz: number, size: number, hue: number, sat: number): void => {
  const uvx = enc(hue, sat);
  const grow = (start: V3, dir: V3, length: number, rad: number, depth: number): void => {
    const pts: V3[] = [start];
    let p = start;
    let d = dir;
    for (let k = 0; k < 3; k += 1) {
      d = norm(add(d, [(r() - 0.5) * 0.3, 0.14, (r() - 0.5) * 0.3]));
      p = add(p, mul(d, length / 3));
      pts.push(p);
    }
    b.tube(pts, (t) => rad * (1 - 0.5 * t), 6, uvx, (t) => 0.6 + 0.4 * t + (depth === 0 ? 0.08 : 0));
    if (depth <= 0) return;
    const kids = depth >= 2 ? 3 : 2;
    for (let k = 0; k < kids; k += 1) {
      let nd = norm(add(d, [(r() - 0.5) * 1.5, r() * 0.3, (r() - 0.5) * 1.5]));
      if (nd[1] < 0.25) nd = norm([nd[0], 0.25, nd[2]]);
      grow(p, nd, length * 0.74, rad * 0.66, depth - 1);
    }
  };
  const base: V3 = [cx, groundY(cx, cz) - 0.08, cz];
  const stems = 4;
  for (let s = 0; s < stems; s += 1) {
    const a = (s / stems) * TAU + r();
    grow(base, norm([Math.cos(a) * 0.55, 1, Math.sin(a) * 0.55]), 0.55 * size, 0.1 * size, 3);
  }
};

/** Rounded brain coral: a dome with a labyrinth of grooves. */
const brain = (b: MeshBuilder, cx: number, cz: number, radius: number, hue: number, sat: number): void => {
  const cy = groundY(cx, cz) + radius * 0.05;
  const uvx = enc(hue, sat);
  const groove = (dx: number, dz: number): number => Math.sin(dx * 17 + 2.2 * Math.sin(dz * 11 + 1)) * Math.sin(dz * 17 + 2.2 * Math.sin(dx * 9));
  b.surface(
    (u, v) => {
      const th = u * TAU;
      const ph = v * (Math.PI / 2) * 1.15;
      const dx = Math.sin(ph) * Math.cos(th);
      const dz = Math.sin(ph) * Math.sin(th);
      const dy = Math.cos(ph);
      const g = groove(dx, dz);
      const rr = radius * (1.03 - 0.07 * Math.exp(-g * g * 18));
      return [cx + dx * rr, cy + dy * rr * 0.72, cz + dz * rr];
    },
    104,
    44,
    (u, v) => {
      const th = u * TAU;
      const ph = v * (Math.PI / 2) * 1.15;
      const g = groove(Math.sin(ph) * Math.cos(th), Math.sin(ph) * Math.sin(th));
      return [uvx, 0.4 + 0.55 * (1 - Math.exp(-g * g * 18))];
    },
    [cx, cy - 0.2, cz]
  );
};

/** Gorgonian sea fan: curved spokes joined by thin cross links, standing on a short stem. */
const seaFan = (b: MeshBuilder, cx: number, cz: number, height: number, yaw: number, hue: number, sat: number): void => {
  const uvx = enc(hue, sat);
  const base: V3 = [cx, groundY(cx, cz) - 0.05, cz];
  const side: V3 = [Math.cos(yaw), 0, -Math.sin(yaw)];
  const depthDir: V3 = [Math.sin(yaw), 0, Math.cos(yaw)];
  const stemTop = add(base, [0, height * 0.22, 0]);
  b.tube([base, add(base, [0, height * 0.12, 0]), stemTop], () => 0.045, 6, uvx, () => 0.55);
  const spokes = 15;
  const spokePoint = (k: number, s: number): V3 => {
    const phi = ((k / (spokes - 1)) - 0.5) * 2 * 1.0;
    const reach = height * 0.78 * s;
    const bend = 0.12 * Math.sin(s * 3 + k * 0.7) + 0.18 * s * s;
    return add(add(stemTop, mul(side, Math.sin(phi) * reach)), add([0, Math.cos(phi) * reach * 0.9, 0], mul(depthDir, bend)));
  };
  const steps = [0, 0.25, 0.5, 0.75, 1];
  for (let k = 0; k < spokes; k += 1) {
    b.tube(steps.map((s) => spokePoint(k, s)), (t) => 0.026 * (1 - 0.55 * t), 4, uvx, (t) => 0.62 + 0.35 * t);
  }
  for (const s of [0.4, 0.6, 0.8, 0.95]) {
    for (let k = 0; k < spokes - 1; k += 1) {
      b.tube([spokePoint(k, s), spokePoint(k + 1, s)], () => 0.011, 4, uvx, () => 0.85);
    }
  }
};

/** Organ-pipe tube coral: a cluster of open tubes. */
const tubes = (b: MeshBuilder, r: () => number, cx: number, cz: number, size: number, hue: number, sat: number): void => {
  const uvx = enc(hue, sat);
  const count = 8;
  for (let i = 0; i < count; i += 1) {
    const a = r() * TAU;
    const off = rnd(r, 0.05, 0.42) * size;
    const x = cx + Math.cos(a) * off;
    const z = cz + Math.sin(a) * off;
    const h = rnd(r, 0.5, 1.15) * size;
    const lean: V3 = [(r() - 0.5) * 0.25 * h, 0, (r() - 0.5) * 0.25 * h];
    const y0 = groundY(x, z) - 0.1;
    const rad = rnd(r, 0.085, 0.13) * size;
    const path: V3[] = [0, 1, 2, 3].map((k) => [x + lean[0] * (k / 3), y0 + (h * k) / 3, z + lean[2] * (k / 3)] as V3);
    b.tube(path, (t) => rad * (1 - 0.25 * t), 10, uvx, (t) => 0.55 + 0.4 * t);
    const top = path[3] as V3;
    b.disc([top[0], top[1] - 0.04, top[2]], rad * 0.72, 10, uvx, 0.12);
  }
};

/** Table coral: a wide, ridged plate on a stalk. */
const table = (b: MeshBuilder, cx: number, cz: number, radius: number, height: number, hue: number, sat: number): void => {
  const uvx = enc(hue, sat);
  const y0 = groundY(cx, cz) - 0.1;
  b.tube([[cx, y0, cz], [cx, y0 + height * 0.5, cz], [cx, y0 + height, cz]], (t) => 0.14 - 0.05 * t, 8, uvx, () => 0.5);
  b.surface(
    (u, v) => {
      const th = u * TAU;
      const rr = v * radius * (1 + 0.09 * Math.sin(7 * th + 1) + 0.05 * Math.sin(13 * th));
      const y = y0 + height + 0.06 * Math.sin(rr * 6) - 0.28 * v * v + 0.05 * Math.sin(th * 3) * v;
      return [cx + Math.cos(th) * rr, y, cz + Math.sin(th) * rr];
    },
    72,
    22,
    (_u, v) => [uvx, 0.6 + 0.3 * (0.5 + 0.5 * Math.sin(v * 30))]
  );
};

const rock = (b: MeshBuilder, r: () => number, cx: number, cz: number, radius: number): void => {
  const seed = r() * 10;
  const uvx = enc(0.09 + r() * 0.04, 0.2);
  const y0 = groundY(cx, cz);
  const shade = 0.35 + r() * 0.2;
  b.surface(
    (u, v) => {
      const th = u * TAU;
      const ph = v * Math.PI;
      const lump = 1 + 0.2 * Math.sin(3 * th + seed) * Math.sin(2 * ph + seed * 0.5) + 0.1 * Math.sin(7 * th + 4 * ph + seed);
      const rr = radius * lump;
      return [cx + Math.sin(ph) * Math.cos(th) * rr * 1.25, y0 + Math.cos(ph) * rr * 0.62, cz + Math.sin(ph) * Math.sin(th) * rr];
    },
    28,
    16,
    (_u, v) => [uvx, shade + 0.25 * (1 - v)],
    [cx, y0 - 0.1, cz]
  );
};

export const buildReef = () => {
  const b = new MeshBuilder();
  const r = makeRng(7331);
  // rocks first so the colonies sit on top of them
  for (let i = 0; i < 16; i += 1) {
    const a = r() * TAU;
    const d = rnd(r, 2.5, 11);
    rock(b, r, Math.cos(a) * d, Math.sin(a) * d, rnd(r, 0.25, 0.85));
  }
  rock(b, r, 0.0, 0.3, 1.1);
  rock(b, r, -3.3, -0.4, 0.8);
  rock(b, r, 3.8, 0.6, 0.9);

  branching(b, r, -1.9, 1.4, 1.35, 0.04, 0.75);
  branching(b, r, 2.9, -2.0, 1.1, 0.93, 0.55);
  branching(b, r, -4.0, -2.4, 1.3, 0.76, 0.5);
  branching(b, r, 1.0, 4.2, 1.0, 0.1, 0.8);
  brain(b, 1.3, 1.8, 0.95, 0.19, 0.6);
  brain(b, -2.9, 3.1, 0.65, 0.02, 0.5);
  brain(b, 4.6, 2.4, 0.55, 0.45, 0.45);
  seaFan(b, 3.6, 1.0, 1.7, 0.5, 0.82, 0.6);
  seaFan(b, -0.3, -3.3, 1.45, -0.4, 0.0, 0.8);
  seaFan(b, -4.6, 0.8, 1.3, 1.2, 0.07, 0.75);
  tubes(b, r, 0.3, -0.6, 1.0, 0.13, 0.85);
  tubes(b, r, 4.8, -0.9, 0.9, 0.6, 0.6);
  tubes(b, r, -3.2, 4.4, 1.0, 0.92, 0.55);
  table(b, 0.8, -2.0, 1.2, 0.75, 0.5, 0.55);
  table(b, -1.2, -5.0, 0.9, 0.55, 0.28, 0.5);
  return b.build({ min: [-30, -2, -30], max: [30, 6, 30] });
};

/** Swaying blades of seaweed. Brightness channel (uv.y) holds the height fraction the shader sways by. */
export const buildSeaweed = () => {
  const b = new MeshBuilder();
  const r = makeRng(99);
  const clumps: Array<[number, number]> = [];
  for (let i = 0; i < 22; i += 1) {
    const a = r() * TAU;
    const d = rnd(r, 2.2, 9.5);
    clumps.push([Math.cos(a) * d, Math.sin(a) * d]);
  }
  for (const [cx, cz] of clumps) {
    const kelp = r() < 0.4;
    const hue = kelp ? rnd(r, 0.09, 0.13) : rnd(r, 0.24, 0.36);
    const uvx = enc(hue, kelp ? 0.7 : 0.75);
    const blades = kelp ? 4 : 8;
    for (let k = 0; k < blades; k += 1) {
      const x = cx + (r() - 0.5) * 0.7;
      const z = cz + (r() - 0.5) * 0.7;
      const y0 = groundY(x, z) - 0.05;
      const h = kelp ? rnd(r, 1.6, 2.7) : rnd(r, 0.8, 1.7);
      const w = kelp ? rnd(r, 0.13, 0.2) : rnd(r, 0.045, 0.08);
      const ang = r() * TAU;
      const lean: V3 = [Math.cos(r() * TAU) * 0.25 * h, 0, Math.sin(r() * TAU) * 0.25 * h];
      const wph = r() * TAU;
      b.surface(
        (u, v) => {
          const wob = 0.05 * Math.sin(v * 5 + wph) * h;
          const cxp = x + lean[0] * v * v + Math.cos(ang) * wob;
          const czp = z + lean[2] * v * v + Math.sin(ang) * wob;
          const width = w * (1 - 0.65 * v) * (kelp ? 1 + 0.25 * Math.sin(v * 22 + wph) : 1);
          return [cxp + Math.cos(ang + 1.57) * (u - 0.5) * width, y0 + h * v, czp + Math.sin(ang + 1.57) * (u - 0.5) * width];
        },
        2,
        12,
        (_u, v) => [uvx, v]
      );
    }
  }
  return b.build({ min: [-30, -2, -30], max: [30, 6, 30] });
};

/** Anemones: a fat column crowned by waving tentacles. */
export const buildAnemones = () => {
  const b = new MeshBuilder();
  const r = makeRng(4242);
  const spots: Array<[number, number, number]> = [
    [0.6, 3.1, 0.93],
    [-1.2, -1.7, 0.06],
    [2.3, -0.2, 0.35],
    [-2.6, 1.2, 0.97],
    [4.1, 3.6, 0.08],
    [-0.2, 5.3, 0.55],
    [-5.2, -0.9, 0.9]
  ];
  for (const [cx, cz, hue] of spots) {
    const y0 = groundY(cx, cz) - 0.05;
    const colU = enc(hue, 0.45);
    b.tube([[cx, y0, cz], [cx, y0 + 0.12, cz], [cx, y0 + 0.24, cz]], (t) => 0.1 + 0.05 * Math.sin(t * 3), 10, colU, () => 0);
    const tentU = enc(hue, 0.6);
    const count = 46;
    for (let i = 0; i < count; i += 1) {
      const a = r() * TAU;
      const rr = Math.sqrt(r()) * 0.12;
      const start: V3 = [cx + Math.cos(a) * rr, y0 + 0.24, cz + Math.sin(a) * rr];
      const outward: V3 = norm([Math.cos(a) * 0.7 + (r() - 0.5) * 0.4, 1, Math.sin(a) * 0.7 + (r() - 0.5) * 0.4]);
      const length = rnd(r, 0.18, 0.32);
      const pts: V3[] = [start];
      let p = start;
      let d = outward;
      for (let k = 0; k < 3; k += 1) {
        d = norm(add(d, [Math.cos(a) * 0.25, 0.02, Math.sin(a) * 0.25]));
        p = add(p, mul(d, length / 3));
        pts.push(p);
      }
      b.tube(pts, (t) => 0.014 * (1 - 0.6 * t), 4, tentU, (t) => 0.3 + 0.7 * t);
    }
  }
  return b.build({ min: [-30, -2, -30], max: [30, 6, 30] });
};

import { group, material, primitives } from "@aura3d/engine";
import { makeRng } from "./mesh";

type Pos = [number, number, number];

export interface Swimmer {
  id: string;
  /** Position and heading (yaw about +Y, radians) at time t. */
  pose: (t: number) => { p: Pos; yaw: number };
}

const fishMat = (color: string, extra: { metallic?: number; roughness?: number } = {}) =>
  material.pbr({ color, roughness: extra.roughness ?? 0.4, metallic: extra.metallic ?? 0.05 });

const dark = fishMat("#0a0f14", { roughness: 0.3 });
const white = fishMat("#f4f8fa", { roughness: 0.3 });

/** Vertical tail fin: wide in Y, thin in Z, apex toward the body (+X). */
const tailFin = (name: string, x: number, spanY: number, length: number, mat: ReturnType<typeof fishMat>, y = 0) =>
  primitives.cone({ name, size: [spanY, length, spanY * 0.14], material: mat }).rotate(0, 0, -Math.PI / 2).position(x, y, 0);

const eyePair = (prefix: string, x: number, y: number, z: number, r: number) => [
  primitives.sphere({ name: `${prefix}-eye-l`, size: r * 2, material: white }).position(x, y, z),
  primitives.sphere({ name: `${prefix}-eye-r`, size: r * 2, material: white }).position(x, y, -z),
  primitives.sphere({ name: `${prefix}-pupil-l`, size: r * 1.2, material: dark }).position(x + r * 0.25, y, z + r * 0.45),
  primitives.sphere({ name: `${prefix}-pupil-r`, size: r * 1.2, material: dark }).position(x + r * 0.25, y, -(z + r * 0.45))
];

/** Small school fish, length about `len` metres, heading +X. */
export const schoolFishNode = (id: string, color: string, len: number, start: Pos) =>
  group(
    id,
    [
      primitives.sphere({ name: `${id}-body`, size: [len, len * 0.42, len * 0.2], material: fishMat(color, { roughness: 0.3, metallic: 0.25 }) }),
      tailFin(`${id}-tail`, -len * 0.52, len * 0.36, len * 0.3, fishMat(color)),
      primitives.sphere({ name: `${id}-stripe`, size: [len * 0.12, len * 0.44, len * 0.21], material: fishMat("#143a66") }).position(len * 0.12, 0, 0)
    ],
    { position: start }
  ).runtime({ id, mutable: true });

export const angelFishNode = (id: string, start: Pos) => {
  const yellow = fishMat("#f5c431", { roughness: 0.35 });
  const blue = fishMat("#2467d1", { roughness: 0.35 });
  return group(
    id,
    [
      primitives.sphere({ name: `${id}-body`, size: [0.5, 0.58, 0.1], material: yellow }),
      primitives.sphere({ name: `${id}-band`, size: [0.1, 0.6, 0.108], material: blue }).position(0.06, 0, 0),
      primitives.sphere({ name: `${id}-band2`, size: [0.07, 0.5, 0.108], material: blue }).position(-0.12, 0, 0),
      primitives.cone({ name: `${id}-dorsal`, size: [0.2, 0.38, 0.03], material: yellow }).position(-0.08, 0.4, 0),
      primitives.cone({ name: `${id}-anal`, size: [0.2, 0.34, 0.03], material: yellow }).rotate(0, 0, Math.PI).position(-0.1, -0.38, 0),
      tailFin(`${id}-tail`, -0.33, 0.3, 0.2, blue),
      ...eyePair(id, 0.2, 0.06, 0.045, 0.03)
    ],
